package cn.nemo.qingxiao;
import android.app.*;import android.content.*;import android.text.InputType;import android.widget.*;import android.util.Base64;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;
public class AppLock {
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("app-lock",0);}
 static boolean enabled(Context c){return prefs(c).contains("hash");}
 static String hash(String pin,byte[] salt)throws Exception {return Base64.encodeToString(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(pin.toCharArray(),salt,100000,256)).getEncoded(),Base64.NO_WRAP);}
 static EditText input(Activity a){EditText t=new EditText(a);t.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);t.setSingleLine();t.setPadding(40,30,40,30);return t;}
 static void unlock(Activity a,Runnable then){if(!enabled(a)){then.run();return;}EditText t=input(a);AlertDialog d=new AlertDialog.Builder(a).setTitle("轻效 Todo · 输入应用密码").setView(t).setCancelable(false).setPositiveButton("解锁",null).setNegativeButton("退出",(x,w)->a.finish()).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{long wait=prefs(a).getLong("wait",0);if(System.currentTimeMillis()<wait){t.setError("请稍后重试");return;}String h=hash(t.getText().toString(),Base64.decode(prefs(a).getString("salt",""),Base64.DEFAULT));if(MessageDigest.isEqual(h.getBytes(),prefs(a).getString("hash","").getBytes())){prefs(a).edit().putInt("fails",0).remove("wait").apply();d.dismiss();then.run();}else{int n=prefs(a).getInt("fails",0)+1;prefs(a).edit().putInt("fails",n).putLong("wait",n>=5?System.currentTimeMillis()+30000:0).apply();t.setError("密码不正确");}}catch(Exception e){t.setError("验证失败");}}));d.show();}
 static void settings(Activity a){unlock(a,()->{if(enabled(a)){new AlertDialog.Builder(a).setTitle("应用密码保护").setItems(new String[]{"更改密码","关闭密码"},(d,w)->{if(w==1){prefs(a).edit().clear().commit();QuadrantWidget.refresh(a);Toast.makeText(a,"应用密码已关闭",Toast.LENGTH_SHORT).show();}else set(a);}).show();}else set(a);});}
 static void set(Activity a){LinearLayout box=new LinearLayout(a);box.setOrientation(1);EditText one=input(a),two=input(a);one.setHint("至少6位密码");two.setHint("再次输入密码");box.addView(one);box.addView(two);AlertDialog d=new AlertDialog.Builder(a).setTitle("设置应用密码").setMessage("仅保护本手机的应用入口。请记住密码，无法通过云端找回。备份文件不含密码。").setView(box).setPositiveButton("保存",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String pin=one.getText().toString();if(pin.length()<6||!pin.equals(two.getText().toString())){two.setError("请填写至少6位且一致的密码");return;}try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);prefs(a).edit().putString("hash",hash(pin,salt)).putString("salt",Base64.encodeToString(salt,Base64.NO_WRAP)).remove("wait").putInt("fails",0).commit();d.dismiss();QuadrantWidget.refresh(a);Toast.makeText(a,"应用密码已开启",Toast.LENGTH_SHORT).show();}catch(Exception e){two.setError("保存失败");}}));d.show();}
}
